<template>
  <div ref="viewport" class="demo-screen-viewport" :class="{ 'is-phone': compact }" aria-hidden="true" inert>
    <iframe inert v-if="active" ref="frame" src="/archive-preview.html" :title="compact ? 'Phone preview' : 'Desktop preview'" tabindex="-1" :style="{ width: `${width}px`, height: `${height}px`, transform: `scale(${scale})`, borderRadius: compact ? `${19 / scale}px` : '0', clipPath: compact ? `inset(0 round ${19 / scale}px)` : 'none' }" />
  </div>
</template>
<script>
export default {
  name: 'ArchiveDemoScreen',
  props: { active: Boolean, compact: Boolean, exhibition: Boolean, visible: Boolean, scene: String, state: Object, playing: Boolean, reducedMotion: Boolean },
  emits: ['ready', 'gallery-ready'],
  data: () => ({ scale: 1, ready: false, dark: false }),
  computed: {
    width() { return this.compact ? 390 : 1440; },
    height() { return this.compact ? 780 : 920; },
  },
  watch: { exhibition() { this.sendFrame(true); }, visible() { this.sendFrame(true); }, state() { this.sendFrame(); }, playing() { this.sendFrame(true); }, dark() { this.sendFrame(true); }, scale() { this.sendFrame(true); } },
  mounted() {
    const resize = entries => {
      const width = entries?.[0]?.contentRect.width ?? parseFloat(getComputedStyle(this.$refs.viewport).width);
      if (width > 0) this.scale = width / this.width;
    };
    this._resize = new ResizeObserver(resize); this._resize.observe(this.$refs.viewport); resize();
    this._onMessage = event => {
      if (event.source !== this.$refs.frame?.contentWindow || event.origin !== location.origin) return;
      if (event.data?.type === 'archive-preview-gallery-ready') this.$emit('gallery-ready');
      if (event.data?.type === 'archive-preview-ready') { this.ready = true; this.sendFrame(true); this.$emit('ready'); }
    };
    window.addEventListener('message', this._onMessage);
    const syncTheme = () => { this.dark = document.body.classList.contains('dark-mode'); };
    this._theme = new MutationObserver(syncTheme); this._theme.observe(document.body, { attributes: true, attributeFilter: ['class'] }); syncTheme();
  },
  beforeUnmount() { this._resize?.disconnect(); this._theme?.disconnect(); window.removeEventListener('message', this._onMessage); },
  methods: {
    sendFrame(force = false) {
      if (!this.ready) return;
      const now = performance.now();
      if (!force && now - (this._lastSent || 0) < (this.scene === 'gallery' ? 12 : 30)) return;
      this._lastSent = now;
      this.$refs.frame.contentWindow.postMessage({ type: 'archive-preview-frame', scene: this.scene, exhibition: this.visible && (this.scene === 'exhibition' || this.scene === 'home'), elapsed: this.state.time, playing: this.playing, dark: this.dark, reducedMotion: this.reducedMotion, cornerRadius: this.compact ? 19 / this.scale : 0 }, location.origin);
    },
  },
};
</script>
<style scoped>
.demo-screen-viewport { position:relative; width:100%; aspect-ratio:1440/920; overflow:hidden; background:var(--demo-paper,#fff); touch-action:pan-y; user-select:none; }
.demo-screen-viewport.is-phone { aspect-ratio:390/780; }
iframe { position:absolute; top:0; left:0; border:0; transform-origin:top left; pointer-events:none; }
.demo-screen-viewport::after{content:"";position:absolute;inset:0;z-index:5;touch-action:pan-y;}
</style>
