<template>
  <div class="ask-question-examples index-ignore" aria-label="Two kinds of questions in Ask">
    <div class="ask-example-switch" role="tablist" aria-label="Question examples"><button v-for="(example,index) in examples" :id="`ask-example-tab-${index}`" :key="example.question" type="button" role="tab" :aria-selected="selected===index" :tabindex="selected===index ? 0 : -1" :aria-controls="`ask-example-panel-${index}`" @click="selected=index" @keydown="switchExample($event,index)">{{example.label}}</button></div>
    <article v-for="(example,index) in examples" :id="`ask-example-panel-${index}`" :key="example.question" class="ask-example" :class="{'is-selected':selected===index,'is-expanded':expanded}">
      <span class="ask-example-kind">{{example.label}}</span>
      <h4 class="ask-example-question"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11a8 8 0 0 1-8 7H8l-5 3 1-6a7 7 0 0 1-1-4 8 8 0 0 1 17 0Z"/><path d="M8 11h.01M12 11h.01M16 11h.01"/></svg>{{example.question}}</h4>
      <p class="ask-example-answer" v-html="example.html"/>
      <AskAnswerAudio v-if="expanded" :text="example.text"/>
      <AskActions v-if="example.actions.length" :actions="example.actions"/>
      <AskViewOffer v-if="example.offer.routing==='offer'" :title="example.offer.title" :description="example.offer.description" @explore="explore(example.question)"/>
      <div v-if="expanded" class="ask-example-sources"><h5>Sources</h5><router-link v-for="source in example.sources" :key="source.id" :to="target(source)">{{source.page}} <span aria-hidden="true">›</span> {{source.title}}</router-link></div>
      <div v-if="expanded" class="ask-example-followups"><h5>Keep exploring</h5><button v-for="question in example.followUps" :key="question" type="button" @click="ask(question)">{{question}}</button></div>
    </article>
    <button type="button" class="ask-example-expand" :aria-expanded="expanded" @click="expanded=!expanded">
      <span>{{ expanded ? 'Show less' : 'Read the full responses' }}</span>
      <svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 8 5 5 5-5"/></svg>
    </button>
  </div>
</template>
<script>
import recorded from '../../data/askGalleryExamples.json';
import { cleanAskAnswer, askViewOffer, askAnswerFollowUps } from '../../utils/askRetrieval';
import { askActionsForDisplay, renderAskAnswerLinks } from '../../utils/askActions';
import { viewSourceTarget } from '../../utils/viewSourceTarget';
import AskAnswerAudio from './AskAnswerAudio.vue';
import AskActions from './AskActions.vue';
import AskViewOffer from './AskViewOffer.vue';
export default {
  name:'AskQuestionExamples',components:{AskAnswerAudio,AskActions,AskViewOffer},
  data:()=>({selected:0,expanded:false,examples:recorded.examples.map(example=>{
    const text=cleanAskAnswer(example.answer),offer=askViewOffer(example.answer);
    return {...example,text,html:renderAskAnswerLinks(text),offer,actions:askActionsForDisplay(example.answer,offer.routing),followUps:askAnswerFollowUps(example.answer)};
  })}),
  methods:{switchExample(event,index){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();this.selected=event.key==='Home'?0:event.key==='End'?this.examples.length-1:(index+(event.key==='ArrowRight'?1:-1)+this.examples.length)%this.examples.length;this.$nextTick(()=>this.$el.querySelector(`#ask-example-tab-${this.selected}`)?.focus({preventScroll:true}));},target:viewSourceTarget,ask(question){window.dispatchEvent(new CustomEvent('open-site-ask',{detail:{question}}));},explore(question){window.dispatchEvent(new CustomEvent('open-site-view',{detail:{question,compose:true}}));}},
};
</script>
<style scoped>
.ask-question-examples{display:grid;grid-template-columns:minmax(0,.74fr) minmax(0,1.26fr);gap:clamp(18px,3vw,40px);margin-top:28px;align-items:stretch}
.ask-example-switch{display:none}
.ask-example:not(.is-expanded) .ask-example-answer{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:4;overflow:hidden;}
.ask-example:not(.is-expanded) :deep(.sp-ask-view-offer-copy span){display:none;}
.ask-example-expand{grid-column:1/-1;display:flex;align-items:center;justify-content:center;gap:9px;min-height:44px;margin-top:-10px;padding:8px 16px;border:0;background:transparent;color:var(--case-muted);font:13px/1.4 'Quattrocento Sans',sans-serif;cursor:var(--site-interactive-cursor,pointer);}
.ask-example-expand svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.2;transition:transform 200ms ease;}
.ask-example-expand[aria-expanded=true] svg{transform:rotate(180deg);}
.ask-example-expand:hover{color:var(--case-ink);}
.ask-example-expand:focus-visible{outline:1px solid currentColor;outline-offset:3px;}

.ask-example{min-width:0;padding:clamp(20px,2.6vw,32px);background:color-mix(in srgb,var(--case-ink) 4%,transparent);}
.ask-example-kind{display:block;color:var(--case-muted);font:11px/1.4 'Quattrocento Sans',sans-serif;letter-spacing:.08em;text-transform:uppercase;margin-bottom:16px}
.ask-example .ask-example-question{display:flex;align-items:flex-start;gap:12px;margin:0 0 25px;font:400 clamp(18px,1.7vw,23px)/1.3 'EB Garamond',Georgia,serif;color:var(--case-ink)}
.ask-example-question svg{width:19px;height:19px;margin-top:5px;flex:none;stroke:currentColor;stroke-width:1.3;fill:none;color:var(--case-muted)}
.ask-example .ask-example-answer{font:15px/1.75 'PT Serif',Georgia,serif;color:var(--case-ink);white-space:pre-line;margin:0 0 22px}
.ask-example :deep(.ask-inline-link){color:inherit;text-decoration:underline;text-decoration-color:color-mix(in srgb,currentColor 35%,transparent);text-underline-offset:3px}
.ask-example :deep(.ask-audio){margin-bottom:24px}
.ask-example :deep(.sp-ask-view-offer){margin-top:20px;flex-wrap:wrap;gap:12px}
.ask-example :deep(.sp-ask-view-offer-copy span){max-width:none}
.ask-example h5{font:10px/1.4 'Quattrocento Sans',sans-serif;letter-spacing:.12em;text-transform:uppercase;color:var(--case-muted);margin:26px 0 10px}
.ask-example-sources a{display:block;width:fit-content;font:12px/1.55 'Quattrocento Sans',sans-serif;color:var(--case-muted);margin:5px 0;text-decoration:underline;text-underline-offset:3px;text-decoration-color:color-mix(in srgb,currentColor 25%,transparent)}
.ask-example-followups button{display:block;text-align:left;border:0;background:color-mix(in srgb,var(--case-ink) 5%,transparent);color:var(--case-muted);font:12px/1.5 'Quattrocento Sans',sans-serif;padding:6px 10px;margin:6px 0;cursor:var(--site-interactive-cursor,pointer);transition:background-color 160ms ease}
.ask-example-followups button:hover{background:color-mix(in srgb,var(--case-ink) 10%,transparent)}
.ask-example-followups button:focus-visible{outline:1px solid currentColor;outline-offset:3px}
@media(max-width:760px){.ask-example-expand{margin-top:8px;}.ask-question-examples{grid-template-columns:1fr;gap:0}.ask-example-switch{display:grid;grid-template-columns:1fr 1fr;background:color-mix(in srgb,var(--case-ink) 4%,transparent);padding:5px;gap:4px;border-radius:4px 4px 0 0}.ask-example-switch button{min-height:44px;border:0;background:transparent;color:var(--case-muted);font:13px/1.3 'Quattrocento Sans',sans-serif;padding:9px 6px;border-radius:3px}.ask-example-switch button[aria-selected=true]{background:var(--case-nav-bg);color:var(--case-ink)}.ask-example:not(.is-selected){display:none}.ask-example-kind{display:none}.ask-example .ask-example-answer{font-size:14px}.ask-example .ask-example-question{font-size:22px}}
</style>
